pub fn draw(&mut self, scene: &Scene) -> bool {
    #[cfg(target_family = "wasm")]
    if self.device_lost() {
        if self.surface_configured {
            log::error!(
                "Browser graphics context was lost; rendering has stopped. Reload the page to recover."
            );
            self.surface_configured = false;
        }
        return false;
    }

    // Bail out early if the surface has been unconfigured (e.g. during
    // Android background/rotation transitions).  Attempting to acquire
    // a texture from an unconfigured surface can block indefinitely on
    // some drivers (Adreno).
    if !self.surface_configured {
        return false;
    }

    let last_error = self.last_error.lock().unwrap().take();
    if let Some(error) = last_error {
        self.failed_frame_count += 1;
        log::error!(
            "GPU error during frame (failure {} of 10): {error}",
            self.failed_frame_count
        );

        // TBD. Does retrying more actually help?
        if self.failed_frame_count > 10 {
            panic!("Too many consecutive GPU errors. Last error: {error}");
        } else if self.failed_frame_count > 5 {
            if let Some(res) = self.resources.as_mut() {
                res.invalidate_intermediate_textures();
            }
            self.atlas.clear();
            self.needs_redraw = true;
            self.failed_frame_count = 0;
            return false;
        }
    } else {
        self.failed_frame_count = 0;
    }

    self.atlas.before_frame();

    let frame = match self.resources().surface.get_current_texture() {
        wgpu::CurrentSurfaceTexture::Success(frame) => frame,
        wgpu::CurrentSurfaceTexture::Suboptimal(frame) => {
            // Textures must be destroyed before the surface can be reconfigured.
            drop(frame);
            let surface_config = self.surface_config.clone();
            let resources = self.resources_mut();
            resources
                .surface
                .configure(&resources.device, &surface_config);
            return false;
        }
        wgpu::CurrentSurfaceTexture::Lost | wgpu::CurrentSurfaceTexture::Outdated => {
            let surface_config = self.surface_config.clone();
            let resources = self.resources_mut();
            resources
                .surface
                .configure(&resources.device, &surface_config);
            return false;
        }
        wgpu::CurrentSurfaceTexture::Timeout | wgpu::CurrentSurfaceTexture::Occluded => {
            return false;
        }
        wgpu::CurrentSurfaceTexture::Validation => {
            *self.last_error.lock().unwrap() =
                Some("Surface texture validation error".to_string());
            return false;
        }
    };

    // Now that we know the surface is healthy, ensure intermediate textures exist
    self.ensure_intermediate_textures();

    let frame_view = frame
        .texture
        .create_view(&wgpu::TextureViewDescriptor::default());

    let gamma_params = GammaParams {
        gamma_ratios: self.rendering_params.gamma_ratios,
        grayscale_enhanced_contrast: self.rendering_params.grayscale_enhanced_contrast,
        subpixel_enhanced_contrast: self.rendering_params.subpixel_enhanced_contrast,
        is_bgr: self.is_bgr as u32,
        _pad: 0,
    };

    let globals = GlobalParams {
        viewport_size: [
            self.surface_config.width as f32,
            self.surface_config.height as f32,
        ],
        premultiplied_alpha: if self.surface_config.alpha_mode
            == wgpu::CompositeAlphaMode::PreMultiplied
        {
            1
        } else {
            0
        },
        pad: 0,
    };

    let path_globals = GlobalParams {
        premultiplied_alpha: 0,
        ..globals
    };

    {
        let resources = self.resources();
        resources.queue.write_buffer(
            &resources.globals_buffer,
            0,
            bytemuck::bytes_of(&globals),
        );
        resources.queue.write_buffer(
            &resources.globals_buffer,
            self.path_globals_offset,
            bytemuck::bytes_of(&path_globals),
        );
        resources.queue.write_buffer(
            &resources.globals_buffer,
            self.gamma_offset,
            bytemuck::bytes_of(&gamma_params),
        );
    }

    if let Err(error) = self.record_frame(scene, &frame_view) {
        log::error!("{error:#}");
        self.resources().queue.submit(std::iter::empty());
        return false;
    }

    frame.present();
    true
}

fn record_frame(&mut self, scene: &Scene, frame_view: &wgpu::TextureView) -> Result<()> {
    let mut instance_offset = 0;
    let instance_bindings = self
        .write_instances(scene, &mut instance_offset)
        .with_context(|| {
            format!(
                "scene too large: {} paths, {} shadows, {} quads, {} underlines, {} monochrome sprites, {} subpixel sprites, {} polychrome sprites",
                scene.paths.len(),
                scene.shadows.len(),
                scene.quads.len(),
                scene.underlines.len(),
                scene.monochrome_sprites.len(),
                scene.subpixel_sprites.len(),
                scene.polychrome_sprites.len(),
            )
        })?;

    let mut encoder =
        self.resources()
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("main_encoder"),
            });

    {
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("main_pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: frame_view,
                resolve_target: None,
                ops: wgpu::Operations {
                    load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                    store: wgpu::StoreOp::Store,
                },
                depth_slice: None,
            })],
            depth_stencil_attachment: None,
            ..Default::default()
        });

        for batch in scene.batches() {
            match batch {
                PrimitiveBatch::Quads(range) => self.draw_instances(
                    &instance_bindings.quads,
                    &self.resources().pipelines.quads,
                    instance_range(range),
                    &mut pass,
                ),
                PrimitiveBatch::Shadows(range) => self.draw_instances(
                    &instance_bindings.shadows,
                    &self.resources().pipelines.shadows,
                    instance_range(range),
                    &mut pass,
                ),
                PrimitiveBatch::Paths(range) => {
                    let paths = &scene.paths[range];
                    if paths.is_empty() {
                        continue;
                    }

                    drop(pass);
                    let rasterized = self.draw_paths_to_intermediate(
                        &mut encoder,
                        paths,
                        &mut instance_offset,
                    )?;

                    pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                        label: Some("main_pass_continued"),
                        color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                            view: frame_view,
                            resolve_target: None,
                            ops: wgpu::Operations {
                                load: wgpu::LoadOp::Load,
                                store: wgpu::StoreOp::Store,
                            },
                            depth_slice: None,
                        })],
                        depth_stencil_attachment: None,
                        ..Default::default()
                    });

                    if rasterized {
                        self.draw_paths_from_intermediate(
                            paths,
                            &mut instance_offset,
                            &mut pass,
                        )?;
                    }
                }
                PrimitiveBatch::Underlines(range) => self.draw_instances(
                    &instance_bindings.underlines,
                    &self.resources().pipelines.underlines,
                    instance_range(range),
                    &mut pass,
                ),
                PrimitiveBatch::MonochromeSprites { texture_id, range } => self.draw_sprites(
                    &instance_bindings.monochrome_sprites,
                    texture_id,
                    &self.resources().pipelines.mono_sprites,
                    instance_range(range),
                    &mut pass,
                ),
                PrimitiveBatch::SubpixelSprites { texture_id, range } => {
                    let resources = self.resources();
                    self.draw_sprites(
                        &instance_bindings.subpixel_sprites,
                        texture_id,
                        resources
                            .pipelines
                            .subpixel_sprites
                            .as_ref()
                            .unwrap_or(&resources.pipelines.mono_sprites),
                        instance_range(range),
                        &mut pass,
                    );
                }
                PrimitiveBatch::PolychromeSprites { texture_id, range } => self.draw_sprites(
                    &instance_bindings.polychrome_sprites,
                    texture_id,
                    &self.resources().pipelines.poly_sprites,
                    instance_range(range),
                    &mut pass,
                ),
                // Surfaces are macOS-only for video playback and are not
                // implemented by the WGPU renderer.
                PrimitiveBatch::Surfaces(_surfaces) => {}
            }
        }
    }

    self.resources()
        .queue
        .submit(std::iter::once(encoder.finish()));
    Ok(())
}

fn write_instances(
    &mut self,
    scene: &Scene,
    instance_offset: &mut u64,
) -> Result<InstanceBindings> {
    Ok(InstanceBindings {
        quads: self.write_instance_binding(
            "quads_bind_group",
            instance_offset,
            &scene.quads,
        )?,
        shadows: self.write_instance_binding(
            "shadows_bind_group",
            instance_offset,
            &scene.shadows,
        )?,
        underlines: self.write_instance_binding(
            "underlines_bind_group",
            instance_offset,
            &scene.underlines,
        )?,
        monochrome_sprites: self.write_instance_binding(
            "monochrome_sprites_bind_group",
            instance_offset,
            &scene.monochrome_sprites,
        )?,
        subpixel_sprites: self.write_instance_binding(
            "subpixel_sprites_bind_group",
            instance_offset,
            &scene.subpixel_sprites,
        )?,
        polychrome_sprites: self.write_instance_binding(
            "polychrome_sprites_bind_group",
            instance_offset,
            &scene.polychrome_sprites,
        )?,
    })
}

