1	@group(1) @binding(0) var t_instances: texture_2d<u32>;
2	
3	// Each texel of `t_instances` packs four 32-bit words of instance data. Records
4	// are read strictly front to back, so all readers share a cursor that keeps the
5	// most recently fetched texel and only touches the texture again when the next
6	// word crosses a texel boundary. This fetches each texel exactly once per
7	// record load instead of once per word. The `read_*` functions must therefore
8	// consume their words in struct declaration order; skipping or re-reading words
9	// would still return correct data (the cursor re-fetches whenever the texel
10	// index changes) but would forfeit the single-fetch-per-texel guarantee.
11	struct InstanceCursor {
12	    word_index: u32,
13	    texel_index: u32,
14	    texel: vec4<u32>,
15	    width: u32,
16	}
17	
18	fn fetch_instance_texel(texel_index: u32, width: u32) -> vec4<u32> {
19	    let coordinate = vec2<i32>(
20	        i32(texel_index % width),
21	        i32(texel_index / width),
22	    );
23	    return textureLoad(t_instances, coordinate, 0);
24	}
25	
26	fn instance_cursor(word_index: u32) -> InstanceCursor {
27	    let width = textureDimensions(t_instances).x;
28	    let texel_index = word_index / 4u;
29	    return InstanceCursor(
30	        word_index,
31	        texel_index,
32	        fetch_instance_texel(texel_index, width),
33	        width,
34	    );
35	}
36	
37	fn read_word(cursor: ptr<function, InstanceCursor>) -> u32 {
38	    let word_index = (*cursor).word_index;
39	    let texel_index = word_index / 4u;
40	    if texel_index != (*cursor).texel_index {
41	        (*cursor).texel = fetch_instance_texel(texel_index, (*cursor).width);
42	        (*cursor).texel_index = texel_index;
43	    }
